  "jumping": {
    "en": ExerciseGuide(["Stand with feet hip-width apart and arms relaxed at your sides.", "Bend your knees, swing your arms and jump straight up.", "Land softly on the balls of your feet with knees slightly bent.", "Do 20 jumps, rest 30 seconds, and repeat for 3 sets."], ["Landing stiff-legged on your heels.", "Letting your knees cave inward on landing."], "Quiet landings mean good control, so try to land like a cat."),
    "tr": ExerciseGuide(["Ayaklarını kalça genişliğinde aç, kolların yanlarda gevşek dursun.", "Dizlerini bük, kollarını savur ve dümdüz yukarı zıpla.", "Dizlerin hafif bükük, ayak tabanının ön kısmına yumuşakça kon.", "20 kez zıpla, 30 saniye dinlen ve 3 set tekrarla."], ["Kaskatı bacaklarla topukların üstüne inmek.", "İnişte dizlerin içe doğru kapanmasına izin vermek."], "Sessiz iniş iyi kontrol demek, bir kedi gibi konmaya çalış."),
    "de": ExerciseGuide(["Stell die Füße hüftbreit hin, die Arme hängen locker.", "Beug die Knie, schwing die Arme und spring gerade nach oben.", "Lande weich auf den Fußballen, die Knie leicht gebeugt.", "Mach 20 Sprünge, 30 Sekunden Pause und insgesamt 3 Sätze."], ["Mit steifen Beinen auf den Fersen landen.", "Bei der Landung die Knie nach innen knicken lassen."], "Leise Landungen zeigen gute Kontrolle, also lande wie eine Katze."),
    "fr": ExerciseGuide(["Place tes pieds à largeur de hanches, bras relâchés le long du corps.", "Plie les genoux, balance les bras et saute bien droit vers le haut.", "Atterris en douceur sur l'avant des pieds, genoux légèrement fléchis.", "Fais 20 sauts, repose-toi 30 secondes et enchaîne 3 séries."], ["Atterrir jambes raides sur les talons.", "Laisser les genoux rentrer vers l'intérieur à la réception."], "Un atterrissage silencieux, c'est du contrôle, alors retombe comme un chat."),
    "es": ExerciseGuide(["Separa los pies al ancho de la cadera, brazos relajados a los lados.", "Flexiona las rodillas, balancea los brazos y salta recto hacia arriba.", "Aterriza suave sobre la parte delantera del pie, rodillas algo flexionadas.", "Haz 20 saltos, descansa 30 segundos y repite 3 series."], ["Caer con las piernas rígidas sobre los talones.", "Dejar que las rodillas se vayan hacia dentro al caer."], "Caer sin hacer ruido es señal de control, así que aterriza como un gato."),
    "it": ExerciseGuide(["Metti i piedi alla larghezza del bacino, braccia rilassate lungo il corpo.", "Piega le ginocchia, slancia le braccia e salta dritto verso l'alto.", "Atterra morbido sull'avampiede, ginocchia leggermente piegate.", "Fai 20 salti, riposa 30 secondi e ripeti per 3 serie."], ["Atterrare a gambe rigide sui talloni.", "Lasciare che le ginocchia vadano verso l'interno all'atterraggio."], "Un atterraggio silenzioso vuol dire controllo, quindi atterra come un gatto."),
    "pt": ExerciseGuide(["Afaste os pés na largura do quadril, braços soltos ao lado do corpo.", "Dobre os joelhos, balance os braços e salte reto para cima.", "Aterrisse suave na parte da frente dos pés, joelhos levemente dobrados.", "Faça 20 saltos, descanse 30 segundos e repita por 3 séries."], ["Cair com as pernas duras em cima dos calcanhares.", "Deixar os joelhos irem para dentro na aterrissagem."], "Aterrissar sem barulho é sinal de controle, então caia como um gato."),
    "hi": ExerciseGuide(["पैर कूल्हों जितनी चौड़ाई पर रखो, हाथ बगल में ढीले छोड़ो।", "घुटने मोड़ो, हाथ झुलाओ और सीधे ऊपर कूदो।", "पंजों के अगले हिस्से पर नरमी से उतरो, घुटने हल्के मुड़े रहें।", "20 बार कूदो, 30 सेकंड आराम करो और 3 सेट दोहराओ।"], ["अकड़े पैरों से एड़ियों पर उतरना।", "उतरते समय घुटनों को अंदर की ओर मुड़ने देना।"], "बिना आवाज़ उतरना अच्छे कंट्रोल की निशानी है, बिल्ली की तरह उतरो।"),
  },
  "swimming_basketball": {
    "en": ExerciseGuide(["Warm up for 5 minutes with easy laps or light dribbling.", "Swim or play for at least 30 minutes at a steady pace.", "Reach fully on every stroke, shot or rebound.", "Cool down with 5 minutes of easy movement and stretching."], ["Skipping the warm-up and starting at full speed.", "Forgetting to drink water while you play."], "Bring a friend; sport is easier to keep up when it is social."),
    "tr": ExerciseGuide(["5 dakika hafif kulaçlarla ya da yavaş top sürerek ısın.", "En az 30 dakika sabit bir tempoyla yüz ya da oyna.", "Her kulaçta, şutta ve ribauntta tam uzan.", "5 dakika hafif hareket ve esnemeyle soğuma yap."], ["Isınmayı atlayıp direkt tam hızla başlamak.", "Oynarken su içmeyi unutmak."], "Bir arkadaşını da çağır, spor birlikte yapılınca daha kolay devam eder."),
    "de": ExerciseGuide(["Wärm dich 5 Minuten mit lockeren Bahnen oder leichtem Dribbeln auf.", "Schwimm oder spiel mindestens 30 Minuten in gleichmäßigem Tempo.", "Streck dich bei jedem Zug, Wurf oder Rebound voll aus.", "Kühl dich 5 Minuten mit lockerer Bewegung und Dehnen ab."], ["Das Aufwärmen auslassen und sofort Vollgas geben.", "Beim Spielen das Trinken vergessen."], "Nimm einen Freund mit, zusammen bleibt man leichter dran."),
    "fr": ExerciseGuide(["Échauffe-toi 5 minutes avec des longueurs tranquilles ou du dribble léger.", "Nage ou joue au moins 30 minutes à un rythme régulier.", "Allonge-toi complètement à chaque mouvement de bras, tir ou rebond.", "Récupère avec 5 minutes de mouvements légers et d'étirements."], ["Sauter l'échauffement et partir à fond.", "Oublier de boire pendant que tu joues."], "Emmène un ami, le sport à plusieurs est plus facile à tenir."),
    "es": ExerciseGuide(["Calienta 5 minutos con largos suaves o botando el balón despacio.", "Nada o juega al menos 30 minutos a un ritmo constante.", "Estírate por completo en cada brazada, tiro o rebote.", "Vuelve a la calma con 5 minutos de movimiento suave y estiramientos."], ["Saltarte el calentamiento y empezar a tope.", "Olvidarte de beber agua mientras juegas."], "Invita a un amigo; el deporte en compañía se mantiene mejor."),
    "it": ExerciseGuide(["Scaldati 5 minuti con vasche tranquille o palleggi leggeri.", "Nuota o gioca per almeno 30 minuti a ritmo costante.", "Allungati del tutto a ogni bracciata, tiro o rimbalzo.", "Defaticati con 5 minuti di movimento leggero e stretching."], ["Saltare il riscaldamento e partire a tutta.", "Dimenticarti di bere mentre giochi."], "Porta un amico; lo sport in compagnia si mantiene più facilmente."),
    "pt": ExerciseGuide(["Aqueça por 5 minutos com voltas leves na piscina ou batendo bola devagar.", "Nade ou jogue por pelo menos 30 minutos em ritmo constante.", "Estique o corpo todo em cada braçada, arremesso ou rebote.", "Desaqueça com 5 minutos de movimento leve e alongamento."], ["Pular o aquecimento e começar com tudo.", "Esquecer de beber água durante o jogo."], "Chame um amigo; esporte em grupo é mais fácil de manter."),
    "hi": ExerciseGuide(["5 मिनट हल्की तैराकी या धीमी ड्रिबलिंग से वार्म-अप करो।", "कम से कम 30 मिनट एक जैसी रफ़्तार से तैरो या खेलो।", "हर स्ट्रोक, शॉट या रिबाउंड में शरीर को पूरा खींचो।", "5 मिनट हल्की हरकत और स्ट्रेचिंग से कूल-डाउन करो।"], ["वार्म-अप छोड़कर सीधे पूरी रफ़्तार से शुरू करना।", "खेलते समय पानी पीना भूल जाना।"], "किसी दोस्त को साथ लाओ, साथ में खेलना जारी रखना आसान होता है।"),
  },
  "evening_yoga": {
    "en": ExerciseGuide(["Start on hands and knees and flow through cat-cow for 60 seconds.", "Sit back into child's pose, arms long, and breathe for 60 seconds.", "Press up into downward dog, heels reaching toward the floor.", "Stand and fold forward, letting your head hang heavy.", "Breathe in for 4 counts and out for 6 counts in every pose."], ["Rushing between poses instead of holding them.", "Forcing a pose until it hurts."], "Dim the lights while you flow to help your body wind down."),
    "tr": ExerciseGuide(["Ellerin ve dizlerin üzerinde başla, 60 saniye kedi-inek akışı yap.", "Çocuk pozuna geç, kollarını öne uzat ve 60 saniye nefes al.", "Aşağı bakan köpek pozuna geç, topuklarını yere doğru uzat.", "Ayakta öne eğil ve başını ağırlığıyla serbest bırak.", "Her pozda 4 sayıda nefes al, 6 sayıda ver."], ["Pozları tutmak yerine aceleyle geçmek.", "Bir pozu canın yanana kadar zorlamak."], "Akış sırasında ışıkları kıs, vücudun gevşemeye hazırlansın."),
    "de": ExerciseGuide(["Starte im Vierfüßlerstand und geh 60 Sekunden fließend durch Katze-Kuh.", "Setz dich in die Kindhaltung, Arme lang, und atme 60 Sekunden.", "Drück dich in den herabschauenden Hund, Fersen Richtung Boden.", "Beug dich im Stehen nach vorn und lass den Kopf schwer hängen.", "Atme in jeder Haltung 4 Zählzeiten ein und 6 aus."], ["Durch die Haltungen hetzen, statt sie zu halten.", "Eine Haltung erzwingen, bis es wehtut."], "Dimm dabei das Licht, damit dein Körper runterfahren kann."),
    "fr": ExerciseGuide(["Commence à quatre pattes et enchaîne chat-vache pendant 60 secondes.", "Assieds-toi en posture de l'enfant, bras tendus, et respire 60 secondes.", "Pousse en chien tête en bas, talons vers le sol.", "Debout, penche-toi en avant et laisse ta tête pendre lourdement.", "Inspire sur 4 temps et expire sur 6 temps dans chaque posture."], ["Enchaîner les postures trop vite sans les tenir.", "Forcer une posture jusqu'à avoir mal."], "Baisse la lumière pendant la séance pour aider ton corps à se détendre."),
    "es": ExerciseGuide(["Empieza en cuatro apoyos y fluye en gato-vaca durante 60 segundos.", "Siéntate en la postura del niño, brazos estirados, y respira 60 segundos.", "Empuja hacia el perro boca abajo, talones hacia el suelo.", "De pie, inclínate hacia delante y deja que la cabeza cuelgue pesada.", "Inhala en 4 tiempos y exhala en 6 en cada postura."], ["Pasar rápido de una postura a otra sin mantenerlas.", "Forzar una postura hasta que duela."], "Baja las luces mientras practicas para que tu cuerpo se relaje."),
    "it": ExerciseGuide(["Parti a quattro zampe e alterna gatto e mucca per 60 secondi.", "Siediti nella posizione del bambino, braccia lunghe, e respira 60 secondi.", "Spingi nel cane a testa in giù, talloni verso il pavimento.", "In piedi, piegati in avanti e lascia la testa pesante.", "Inspira in 4 tempi ed espira in 6 in ogni posizione."], ["Passare di fretta da una posizione all'altra senza tenerle.", "Forzare una posizione fino a sentire dolore."], "Abbassa le luci mentre pratichi per aiutare il corpo a rilassarsi."),
    "pt": ExerciseGuide(["Comece em quatro apoios e faça o gato-vaca por 60 segundos.", "Sente na postura da criança, braços esticados, e respire por 60 segundos.", "Empurre para o cachorro olhando para baixo, calcanhares em direção ao chão.", "Em pé, incline o tronco para frente e deixe a cabeça pender pesada.", "Inspire em 4 tempos e expire em 6 em cada postura."], ["Passar correndo pelas posturas sem segurar.", "Forçar uma postura até doer."], "Diminua as luzes durante a prática para ajudar o corpo a relaxar."),
    "hi": ExerciseGuide(["हाथों और घुटनों के बल शुरू करो और 60 सेकंड कैट-काउ करो।", "बालासन में बैठो, हाथ आगे फैलाओ और 60 सेकंड साँस लो।", "अधोमुख श्वानासन में जाओ, एड़ियाँ ज़मीन की ओर रखो।", "खड़े होकर आगे झुको और सिर को ढीला लटकने दो।", "हर आसन में 4 गिनती तक साँस लो और 6 गिनती तक छोड़ो।"], ["आसन में रुकने की बजाय जल्दी-जल्दी बदलना।", "किसी आसन को दर्द होने तक ज़बरदस्ती करना।"], "अभ्यास के दौरान रोशनी धीमी कर दो ताकि शरीर शांत हो सके।"),
  },
  "sprint_intervals": {
    "en": ExerciseGuide(["Warm up with 5 minutes of easy jogging and leg swings.", "Sprint at full effort for 30 seconds, pumping your arms.", "Walk or jog slowly for 90 seconds to recover.", "Repeat for 3 sprints, then cool down with 5 minutes of walking."], ["Sprinting without warming up first.", "Leaning back and overstriding instead of driving forward."], "Pick a flat, safe surface and go all out only when you feel fresh."),
    "tr": ExerciseGuide(["5 dakika hafif koşu ve bacak sallamalarıyla ısın.", "30 saniye tüm gücünle depar at, kollarını güçlü salla.", "Toparlanmak için 90 saniye yürü ya da yavaş koş.", "3 depar tamamla, sonra 5 dakika yürüyerek soğuma yap."], ["Isınmadan depara kalkmak.", "Öne doğru itmek yerine geriye yaslanıp adımı fazla açmak."], "Düz ve güvenli bir zemin seç, tam gücü sadece dinçken ver."),
    "de": ExerciseGuide(["Wärm dich 5 Minuten mit lockerem Joggen und Beinschwüngen auf.", "Sprinte 30 Sekunden mit voller Kraft und arbeite kräftig mit den Armen.", "Geh oder jogge 90 Sekunden locker, um dich zu erholen.", "Mach 3 Sprints und geh danach 5 Minuten zum Abkühlen."], ["Ohne Aufwärmen lossprinten.", "Nach hinten lehnen und viel zu große Schritte machen."], "Such dir einen ebenen, sicheren Untergrund und gib nur Vollgas, wenn du frisch bist."),
    "fr": ExerciseGuide(["Échauffe-toi 5 minutes avec un footing léger et des balancés de jambes.", "Sprinte à fond pendant 30 secondes en poussant fort avec les bras.", "Marche ou trottine 90 secondes pour récupérer.", "Fais 3 sprints, puis marche 5 minutes pour revenir au calme."], ["Sprinter sans t'échauffer.", "Te pencher en arrière avec des foulées trop longues."], "Choisis une surface plate et sûre, et donne tout seulement quand tu es frais."),
    "es": ExerciseGuide(["Calienta 5 minutos trotando suave y con balanceos de piernas.", "Esprinta 30 segundos a máximo esfuerzo, moviendo fuerte los brazos.", "Camina o trota suave 90 segundos para recuperarte.", "Haz 3 sprints y luego camina 5 minutos para enfriar."], ["Esprintar sin calentar antes.", "Echarte hacia atrás y dar zancadas demasiado largas."], "Busca una superficie plana y segura, y da el máximo solo cuando estés fresco."),
    "it": ExerciseGuide(["Scaldati 5 minuti con corsa leggera e slanci delle gambe.", "Scatta al massimo per 30 secondi, spingendo forte con le braccia.", "Cammina o corri piano per 90 secondi per recuperare.", "Fai 3 scatti, poi cammina 5 minuti per defaticarti."], ["Scattare senza esserti scaldato.", "Inclinarti indietro e fare passi troppo lunghi."], "Scegli una superficie piana e sicura e spingi al massimo solo quando sei fresco."),
    "pt": ExerciseGuide(["Aqueça por 5 minutos com trote leve e balanços de perna.", "Corra no máximo por 30 segundos, movendo bem os braços.", "Caminhe ou trote devagar por 90 segundos para se recuperar.", "Faça 3 tiros e depois caminhe 5 minutos para desaquecer."], ["Dar tiros sem aquecer antes.", "Inclinar o corpo para trás e dar passadas longas demais."], "Escolha um piso plano e seguro e só vá no máximo quando estiver descansado."),
    "hi": ExerciseGuide(["5 मिनट हल्की जॉगिंग और पैर झुलाकर वार्म-अप करो।", "30 सेकंड पूरी ताकत से दौड़ो, हाथों को ज़ोर से चलाओ।", "रिकवरी के लिए 90 सेकंड चलो या धीरे जॉग करो।", "3 स्प्रिंट पूरे करो, फिर 5 मिनट चलकर कूल-डाउन करो।"], ["बिना वार्म-अप के स्प्रिंट करना।", "पीछे झुककर बहुत लंबे कदम रखना।"], "समतल और सुरक्षित जगह चुनो, और पूरी ताकत तभी लगाओ जब ताज़ा महसूस करो।"),
  },
  "hiit_workout": {
    "en": ExerciseGuide(["Warm up for 3 minutes with marching in place and arm circles.", "Do burpees, mountain climbers and jump squats, 45 seconds each.", "Rest 15 seconds between moves and breathe deeply.", "Complete 4 rounds, then walk slowly until your breathing settles."], ["Letting your form slip to go faster.", "Holding your breath during the hard intervals."], "Go at your own pace; finishing all 4 rounds beats a fast start."),
    "tr": ExerciseGuide(["3 dakika yerinde yürüyüp kol çevirerek ısın.", "Burpee, mountain climber ve squat jump yap, her biri 45 saniye.", "Hareketler arasında 15 saniye dinlen ve derin nefes al.", "4 tur tamamla, sonra nefesin düzelene kadar yavaşça yürü."], ["Hızlanmak için formu bozmak.", "Zor aralıklarda nefesini tutmak."], "Kendi temponda git, 4 turu bitirmek hızlı başlamaktan daha değerli."),
    "de": ExerciseGuide(["Wärm dich 3 Minuten mit Marschieren auf der Stelle und Armkreisen auf.", "Mach Burpees, Mountain Climbers und Squat Jumps, je 45 Sekunden.", "Ruh dich zwischen den Übungen 15 Sekunden aus und atme tief.", "Schaff 4 Runden und geh danach locker, bis dein Atem ruhig ist."], ["Für mehr Tempo die saubere Technik aufgeben.", "In den harten Intervallen die Luft anhalten."], "Geh dein eigenes Tempo; alle 4 Runden zu schaffen schlägt einen schnellen Start."),
    "fr": ExerciseGuide(["Échauffe-toi 3 minutes en marchant sur place avec des cercles de bras.", "Fais des burpees, des mountain climbers et des squats sautés, 45 secondes chacun.", "Repose-toi 15 secondes entre les exercices en respirant profondément.", "Termine 4 tours, puis marche doucement jusqu'à retrouver ton souffle."], ["Sacrifier la technique pour aller plus vite.", "Bloquer ta respiration pendant les efforts intenses."], "Va à ton rythme, finir les 4 tours vaut mieux qu'un départ trop rapide."),
    "es": ExerciseGuide(["Calienta 3 minutos marchando en el sitio y haciendo círculos con los brazos.", "Haz burpees, escaladores y sentadillas con salto, 45 segundos cada uno.", "Descansa 15 segundos entre ejercicios y respira hondo.", "Completa 4 rondas y camina despacio hasta que se calme tu respiración."], ["Sacrificar la técnica para ir más rápido.", "Aguantar la respiración en los intervalos duros."], "Ve a tu ritmo; terminar las 4 rondas vale más que empezar rápido."),
    "it": ExerciseGuide(["Scaldati 3 minuti marciando sul posto e facendo cerchi con le braccia.", "Fai burpees, mountain climber e squat jump, 45 secondi ciascuno.", "Riposa 15 secondi tra un esercizio e l'altro e respira a fondo.", "Completa 4 giri, poi cammina piano finché il respiro si calma."], ["Sacrificare la tecnica per andare più veloce.", "Trattenere il respiro negli intervalli più duri."], "Vai al tuo ritmo; finire tutti e 4 i giri batte una partenza veloce."),
    "pt": ExerciseGuide(["Aqueça por 3 minutos marchando no lugar e girando os braços.", "Faça burpees, escalador e agachamento com salto, 45 segundos cada.", "Descanse 15 segundos entre os exercícios e respire fundo.", "Complete 4 rodadas e caminhe devagar até a respiração acalmar."], ["Sacrificar a técnica para ir mais rápido.", "Prender a respiração nos intervalos mais fortes."], "Vá no seu ritmo; terminar as 4 rodadas vale mais que começar rápido."),
    "hi": ExerciseGuide(["3 मिनट एक जगह मार्च करके और हाथ घुमाकर वार्म-अप करो।", "बर्पी, माउंटेन क्लाइंबर और जंप स्क्वैट करो, हर एक 45 सेकंड।", "हर एक्सरसाइज़ के बीच 15 सेकंड आराम करो और गहरी साँस लो।", "4 राउंड पूरे करो, फिर साँस सामान्य होने तक धीरे चलो।"], ["तेज़ी के चक्कर में सही फ़ॉर्म छोड़ देना।", "मुश्किल अंतराल में साँस रोक लेना।"], "अपनी रफ़्तार से करो, चारों राउंड पूरे करना तेज़ शुरुआत से बेहतर है।"),
  },
  "squats": {
    "en": ExerciseGuide(["Stand with feet shoulder-width apart, toes turned slightly out.", "Push your hips back and lower until your thighs are parallel to the floor.", "Keep your chest up and your knees in line with your toes.", "Press through your heels to stand, breathing out on the way up."], ["Lifting your heels off the floor.", "Rounding your back at the bottom."], "Do your first sets in front of a mirror to check your form."),
    "tr": ExerciseGuide(["Ayaklarını omuz genişliğinde aç, parmak uçların hafif dışa baksın.", "Kalçanı geriye it, uylukların yere paralel olana kadar in.", "Göğsünü dik tut, dizlerin ayak parmaklarınla aynı yöne baksın.", "Topuklarından iterek kalk, kalkarken nefes ver."], ["Topukları yerden kaldırmak.", "En altta sırtı yuvarlamak."], "İlk setleri ayna karşısında yap, formunu kolayca kontrol edersin."),
    "de": ExerciseGuide(["Stell die Füße schulterbreit hin, die Zehen zeigen leicht nach außen.", "Schieb die Hüfte nach hinten und geh runter, bis die Oberschenkel parallel zum Boden sind.", "Halte die Brust oben und die Knie in Richtung Zehen.", "Drück dich über die Fersen hoch und atme dabei aus."], ["Die Fersen vom Boden heben.", "Unten den Rücken rund machen."], "Mach die ersten Sätze vor dem Spiegel, um deine Technik zu checken."),
    "fr": ExerciseGuide(["Place tes pieds à largeur d'épaules, pointes légèrement vers l'extérieur.", "Pousse les hanches en arrière et descends jusqu'à avoir les cuisses parallèles au sol.", "Garde la poitrine haute et les genoux dans l'axe des orteils.", "Pousse sur les talons pour remonter en expirant."], ["Décoller les talons du sol.", "Arrondir le dos en bas du mouvement."], "Fais tes premières séries face à un miroir pour vérifier ta technique."),
    "es": ExerciseGuide(["Separa los pies al ancho de los hombros, puntas un poco hacia fuera.", "Lleva la cadera atrás y baja hasta que los muslos queden paralelos al suelo.", "Mantén el pecho arriba y las rodillas en línea con los pies.", "Empuja con los talones para subir y suelta el aire al subir."], ["Levantar los talones del suelo.", "Redondear la espalda abajo."], "Haz las primeras series frente a un espejo para revisar tu técnica."),
    "it": ExerciseGuide(["Metti i piedi alla larghezza delle spalle, punte un po' in fuori.", "Porta il bacino indietro e scendi finché le cosce sono parallele al pavimento.", "Tieni il petto alto e le ginocchia in linea con le punte dei piedi.", "Spingi sui talloni per risalire ed espira mentre sali."], ["Sollevare i talloni da terra.", "Arrotondare la schiena in basso."], "Fai le prime serie davanti a uno specchio per controllare la tecnica."),
    "pt": ExerciseGuide(["Afaste os pés na largura dos ombros, pontas um pouco para fora.", "Leve o quadril para trás e desça até as coxas ficarem paralelas ao chão.", "Mantenha o peito aberto e os joelhos alinhados com os pés.", "Empurre pelos calcanhares para subir, soltando o ar na subida."], ["Tirar os calcanhares do chão.", "Arredondar as costas lá embaixo."], "Faça as primeiras séries na frente do espelho para conferir a postura."),
    "hi": ExerciseGuide(["पैर कंधों जितनी चौड़ाई पर रखो, पंजे थोड़े बाहर की ओर।", "कूल्हे पीछे धकेलो और जांघें ज़मीन के समानांतर होने तक नीचे जाओ।", "छाती ऊपर रखो और घुटनों को पैरों की उंगलियों की सीध में रखो।", "एड़ियों से ज़ोर लगाकर ऊपर आओ और उठते समय साँस छोड़ो।"], ["एड़ियाँ ज़मीन से उठा देना।", "नीचे जाकर पीठ गोल कर लेना।"], "पहले कुछ सेट शीशे के सामने करो ताकि अपना फ़ॉर्म देख सको।"),
  },
  "deadlift_stretch": {
    "en": ExerciseGuide(["Stand with feet hip-width apart and knees softly bent.", "Hinge at your hips and slide your hands down your thighs.", "Keep your back flat and reach toward your toes until your hamstrings stretch.", "Squeeze your glutes to stand back up, 12 slow reps per set."], ["Rounding your back to reach lower.", "Locking your knees completely straight."], "Move slowly; control matters more than how far you reach."),
    "tr": ExerciseGuide(["Ayaklarını kalça genişliğinde aç, dizlerin hafif bükük olsun.", "Kalçandan menteşe gibi eğil, ellerini uylukların boyunca aşağı kaydır.", "Sırtını düz tut, bacaklarının arkasında gerilme hissedene kadar uzan.", "Kalça kaslarını sıkarak doğrul, her sette 12 yavaş tekrar yap."], ["Daha aşağı uzanmak için sırtı yuvarlamak.", "Dizleri tamamen kilitlemek."], "Yavaş hareket et, ne kadar uzandığından çok kontrol önemli."),
    "de": ExerciseGuide(["Stell die Füße hüftbreit hin, die Knie leicht gebeugt.", "Kipp aus der Hüfte nach vorn und schieb die Hände die Oberschenkel hinab.", "Halte den Rücken gerade und reich Richtung Zehen, bis die Beinrückseite zieht.", "Spann den Po an, um dich aufzurichten, 12 langsame Wiederholungen pro Satz."], ["Den Rücken rund machen, um tiefer zu kommen.", "Die Knie komplett durchdrücken."], "Beweg dich langsam; Kontrolle zählt mehr als die Reichweite."),
    "fr": ExerciseGuide(["Place tes pieds à largeur de hanches, genoux légèrement fléchis.", "Bascule depuis les hanches en faisant glisser tes mains le long des cuisses.", "Garde le dos plat et descends vers tes orteils jusqu'à sentir l'arrière des cuisses.", "Serre les fessiers pour remonter, 12 répétitions lentes par série."], ["Arrondir le dos pour descendre plus bas.", "Verrouiller complètement les genoux."], "Va lentement, le contrôle compte plus que la distance."),
    "es": ExerciseGuide(["Separa los pies al ancho de la cadera, rodillas un poco flexionadas.", "Inclínate desde la cadera y desliza las manos por los muslos.", "Mantén la espalda recta y baja hasta notar el estiramiento detrás de las piernas.", "Aprieta los glúteos para subir, 12 repeticiones lentas por serie."], ["Redondear la espalda para llegar más abajo.", "Bloquear las rodillas totalmente rectas."], "Muévete despacio; el control importa más que hasta dónde llegas."),
    "it": ExerciseGuide(["Metti i piedi alla larghezza del bacino, ginocchia leggermente piegate.", "Piegati dalle anche facendo scivolare le mani lungo le cosce.", "Tieni la schiena piatta e scendi verso i piedi finché senti tirare dietro le cosce.", "Stringi i glutei per risalire, 12 ripetizioni lente per serie."], ["Arrotondare la schiena per scendere di più.", "Bloccare le ginocchia completamente tese."], "Muoviti piano; il controllo conta più di quanto scendi."),
    "pt": ExerciseGuide(["Afaste os pés na largura do quadril, joelhos levemente dobrados.", "Incline o tronco a partir do quadril, deslizando as mãos pelas coxas.", "Mantenha as costas retas e desça até sentir alongar atrás das pernas.", "Contraia os glúteos para subir, 12 repetições lentas por série."], ["Arredondar as costas para descer mais.", "Travar os joelhos totalmente esticados."], "Vá devagar; o controle importa mais do que até onde você chega."),
    "hi": ExerciseGuide(["पैर कूल्हों जितनी चौड़ाई पर रखो, घुटने हल्के मुड़े रहें।", "कूल्हों से आगे झुको और हाथों को जांघों पर नीचे सरकाओ।", "पीठ सीधी रखो और जांघों के पीछे खिंचाव महसूस होने तक पंजों की ओर जाओ।", "ग्लूट्स कसते हुए सीधे खड़े हो जाओ, हर सेट में 12 धीमे रेप्स करो।"], ["और नीचे पहुँचने के लिए पीठ गोल करना।", "घुटनों को पूरी तरह लॉक कर देना।"], "धीरे करो, कितना नीचे पहुँचे उससे ज़्यादा कंट्रोल मायने रखता है।"),
  },
  "overhead_press": {
    "en": ExerciseGuide(["Stand tall holding light weights or water bottles at shoulder height.", "Brace your core and press both arms straight overhead.", "Finish with arms beside your ears, then lower slowly to your shoulders.", "Breathe out as you press, in as you lower, 10 reps per set."], ["Arching your lower back as you press.", "Using weights too heavy to control."], "Start with bodyweight and add light weights once your form feels easy."),
    "tr": ExerciseGuide(["Dik dur, hafif ağırlıkları ya da su şişelerini omuz hizasında tut.", "Karnını sık ve iki kolunu dümdüz yukarı it.", "Kolların kulaklarının yanında bitsin, sonra yavaşça omuzlara indir.", "İterken nefes ver, indirirken al, her sette 10 tekrar yap."], ["İterken belini çukurlaştırmak.", "Kontrol edemeyeceğin kadar ağır ağırlık kullanmak."], "Önce vücut ağırlığınla başla, form rahatlayınca hafif ağırlık ekle."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, leichte Gewichte oder Wasserflaschen auf Schulterhöhe.", "Spann den Bauch an und drück beide Arme gerade nach oben.", "Oben sind die Arme neben den Ohren, dann senk sie langsam zu den Schultern.", "Beim Drücken ausatmen, beim Senken einatmen, 10 Wiederholungen pro Satz."], ["Beim Drücken ins Hohlkreuz gehen.", "Zu schwere Gewichte nehmen, die du nicht kontrollierst."], "Starte mit deinem Körpergewicht und nimm leichte Gewichte erst dazu, wenn die Technik sitzt."),
    "fr": ExerciseGuide(["Tiens-toi droit, poids légers ou bouteilles d'eau à hauteur d'épaules.", "Gaine ton ventre et pousse les deux bras tendus au-dessus de la tête.", "Finis les bras près des oreilles, puis redescends lentement aux épaules.", "Expire en poussant, inspire en descendant, 10 répétitions par série."], ["Creuser le bas du dos en poussant.", "Prendre des poids trop lourds pour être contrôlés."], "Commence sans poids et ajoute des charges légères quand le mouvement devient facile."),
    "es": ExerciseGuide(["Ponte recto con pesas ligeras o botellas de agua a la altura de los hombros.", "Aprieta el abdomen y empuja los dos brazos rectos hacia arriba.", "Termina con los brazos junto a las orejas y baja despacio a los hombros.", "Suelta el aire al empujar y tómalo al bajar, 10 repeticiones por serie."], ["Arquear la zona lumbar al empujar.", "Usar un peso demasiado pesado para controlarlo."], "Empieza sin peso y añade algo ligero cuando la técnica te salga fácil."),
    "it": ExerciseGuide(["Stai dritto con pesi leggeri o bottiglie d'acqua all'altezza delle spalle.", "Contrai l'addome e spingi entrambe le braccia dritte sopra la testa.", "Finisci con le braccia vicino alle orecchie, poi scendi piano alle spalle.", "Espira mentre spingi, inspira mentre scendi, 10 ripetizioni per serie."], ["Inarcare la zona lombare mentre spingi.", "Usare pesi troppo pesanti da controllare."], "Inizia a corpo libero e aggiungi pesi leggeri quando la tecnica ti viene facile."),
    "pt": ExerciseGuide(["Fique reto com pesos leves ou garrafas de água na altura dos ombros.", "Contraia o abdômen e empurre os dois braços retos para cima.", "Termine com os braços ao lado das orelhas e desça devagar até os ombros.", "Solte o ar ao empurrar e puxe ao descer, 10 repetições por série."], ["Arquear a lombar ao empurrar.", "Usar peso pesado demais para controlar."], "Comece sem peso e só acrescente carga leve quando a técnica estiver fácil."),
    "hi": ExerciseGuide(["सीधे खड़े होकर हल्के वज़न या पानी की बोतलें कंधों की ऊँचाई पर पकड़ो।", "पेट कसो और दोनों हाथ सीधे सिर के ऊपर धकेलो।", "ऊपर हाथ कानों के पास हों, फिर धीरे से कंधों तक नीचे लाओ।", "धकेलते समय साँस छोड़ो, नीचे लाते समय लो, हर सेट में 10 रेप्स।"], ["धकेलते समय कमर को पीछे की ओर मोड़ना।", "इतना भारी वज़न लेना जिसे संभाल न सको।"], "बिना वज़न के शुरू करो और फ़ॉर्म आसान लगे तभी हल्का वज़न जोड़ो।"),
  },
  "skipping_rope": {
    "en": ExerciseGuide(["Hold the handles at hip height, elbows close to your sides.", "Turn the rope with your wrists, not your whole arms.", "Jump just high enough to clear the rope, landing on the balls of your feet.", "Skip for 5 minutes, rest 1 minute, and repeat for 3 sets."], ["Jumping too high and tiring out fast.", "Landing flat-footed on your heels."], "Tripping is normal; just restart and keep the rhythm going."),
    "tr": ExerciseGuide(["Sapları kalça hizasında tut, dirseklerin vücuduna yakın olsun.", "İpi tüm kolunla değil, bileklerinle çevir.", "İpin geçeceği kadar zıpla, ayak tabanının ön kısmına kon.", "5 dakika atla, 1 dakika dinlen ve 3 set tekrarla."], ["Çok yükseğe zıplayıp hemen yorulmak.", "Düz tabanla topukların üstüne inmek."], "İpe takılmak normal, hemen yeniden başla ve ritmini koru."),
    "de": ExerciseGuide(["Halte die Griffe auf Hüfthöhe, die Ellbogen nah am Körper.", "Dreh das Seil aus den Handgelenken, nicht mit den ganzen Armen.", "Spring nur so hoch wie nötig und lande auf den Fußballen.", "Spring 5 Minuten, mach 1 Minute Pause und insgesamt 3 Sätze."], ["Zu hoch springen und schnell müde werden.", "Flach auf den Fersen landen."], "Hängenbleiben ist normal, starte einfach neu und halte den Rhythmus."),
    "fr": ExerciseGuide(["Tiens les poignées à hauteur de hanches, coudes près du corps.", "Fais tourner la corde avec les poignets, pas avec tout le bras.", "Saute juste assez pour passer la corde et retombe sur l'avant des pieds.", "Saute 5 minutes, repose-toi 1 minute et fais 3 séries."], ["Sauter trop haut et t'épuiser vite.", "Retomber à plat sur les talons."], "Se prendre les pieds dans la corde, c'est normal, reprends et garde le rythme."),
    "es": ExerciseGuide(["Sujeta los mangos a la altura de la cadera, codos pegados al cuerpo.", "Gira la cuerda con las muñecas, no con todo el brazo.", "Salta lo justo para pasar la cuerda y cae en la parte delantera del pie.", "Salta 5 minutos, descansa 1 minuto y repite 3 series."], ["Saltar demasiado alto y cansarte rápido.", "Caer con el pie plano sobre los talones."], "Enredarte con la cuerda es normal; vuelve a empezar y mantén el ritmo."),
    "it": ExerciseGuide(["Tieni le maniglie all'altezza dei fianchi, gomiti vicini al corpo.", "Fai girare la corda con i polsi, non con tutto il braccio.", "Salta solo quanto basta per superare la corda, atterrando sull'avampiede.", "Salta 5 minuti, riposa 1 minuto e ripeti per 3 serie."], ["Saltare troppo in alto e stancarti subito.", "Atterrare a piedi piatti sui talloni."], "Inciampare è normale; riparti subito e tieni il ritmo."),
    "pt": ExerciseGuide(["Segure os cabos na altura do quadril, cotovelos perto do corpo.", "Gire a corda com os punhos, não com o braço inteiro.", "Pule só o necessário para passar a corda, caindo na parte da frente dos pés.", "Pule por 5 minutos, descanse 1 minuto e repita por 3 séries."], ["Pular alto demais e cansar rápido.", "Cair com o pé chapado nos calcanhares."], "Errar o pulo é normal; recomece e mantenha o ritmo."),
    "hi": ExerciseGuide(["हैंडल कूल्हों की ऊँचाई पर पकड़ो, कोहनियाँ शरीर के पास रखो।", "रस्सी पूरे हाथ से नहीं, कलाइयों से घुमाओ।", "बस उतना कूदो कि रस्सी निकल जाए, और पंजों के अगले हिस्से पर उतरो।", "5 मिनट कूदो, 1 मिनट आराम करो और 3 सेट दोहराओ।"], ["बहुत ऊँचा कूदकर जल्दी थक जाना।", "सपाट पैर से एड़ियों पर उतरना।"], "रस्सी में अटकना सामान्य है, फिर से शुरू करो और लय बनाए रखो।"),
  },
  "pilates_core": {
    "en": ExerciseGuide(["Hold a forearm plank for 1 minute, body in one straight line.", "Lie on your back for dead bugs, lowering opposite arm and leg slowly.", "Switch to bird dog on hands and knees, reaching opposite arm and leg.", "Finish with 1 minute of glute bridges and 1 minute of leg raises.", "Breathe out every time you tighten your core."], ["Letting your hips sag during the plank.", "Arching your lower back off the floor during dead bugs."], "Slow and controlled beats fast; every clean rep builds real strength."),
    "tr": ExerciseGuide(["Dirseklerinin üzerinde 1 dakika plank yap, vücudun dümdüz olsun.", "Sırtüstü dead bug yap, karşı kol ve bacağı yavaşça indir.", "Eller ve dizler üzerinde bird dog'a geç, karşı kol ve bacağı uzat.", "1 dakika kalça köprüsü ve 1 dakika bacak kaldırmayla bitir.", "Karnını her sıktığında nefes ver."], ["Plankta kalçanın aşağı sarkması.", "Dead bug sırasında belin yerden kalkması."], "Yavaş ve kontrollü, hızlıdan iyidir; her temiz tekrar seni gerçekten güçlendirir."),
    "de": ExerciseGuide(["Halte 1 Minute einen Unterarmstütz, dein Körper bildet eine gerade Linie.", "Mach in Rückenlage Dead Bugs und senk Arm und Gegenbein langsam ab.", "Wechsle in den Vierfüßlerstand zum Bird Dog und streck Arm und Gegenbein.", "Schließ mit je 1 Minute Beckenheben und Beinheben ab.", "Atme jedes Mal aus, wenn du den Bauch anspannst."], ["Im Unterarmstütz die Hüfte durchhängen lassen.", "Beim Dead Bug den unteren Rücken vom Boden heben."], "Langsam und kontrolliert schlägt schnell; jede saubere Wiederholung macht dich stärker."),
    "fr": ExerciseGuide(["Tiens une planche sur les avant-bras 1 minute, corps bien aligné.", "Sur le dos, fais le dead bug en descendant lentement bras et jambe opposés.", "Passe à quatre pattes en bird dog et tends bras et jambe opposés.", "Termine par 1 minute de pont fessier et 1 minute de levées de jambes.", "Expire chaque fois que tu contractes tes abdos."], ["Laisser les hanches s'affaisser pendant la planche.", "Décoller le bas du dos du sol pendant le dead bug."], "Lent et contrôlé vaut mieux que rapide, chaque répétition propre te rend plus fort."),
    "es": ExerciseGuide(["Mantén una plancha sobre los antebrazos 1 minuto, cuerpo en línea recta.", "Boca arriba, haz dead bug bajando despacio brazo y pierna contrarios.", "Pasa a cuatro apoyos en bird dog, estirando brazo y pierna contrarios.", "Termina con 1 minuto de puente de glúteos y 1 minuto de elevación de piernas.", "Suelta el aire cada vez que aprietes el abdomen."], ["Dejar caer la cadera en la plancha.", "Despegar la zona lumbar del suelo en el dead bug."], "Lento y controlado gana a rápido; cada buena repetición te hace más fuerte."),
    "it": ExerciseGuide(["Tieni un plank sugli avambracci per 1 minuto, corpo in linea retta.", "Sulla schiena, fai il dead bug abbassando piano braccio e gamba opposti.", "Passa a quattro zampe nel bird dog, allungando braccio e gamba opposti.", "Chiudi con 1 minuto di ponte glutei e 1 minuto di sollevamento gambe.", "Espira ogni volta che contrai l'addome."], ["Far cedere il bacino durante il plank.", "Staccare la zona lombare da terra nel dead bug."], "Lento e controllato batte veloce; ogni ripetizione fatta bene ti rende più forte."),
    "pt": ExerciseGuide(["Segure uma prancha nos antebraços por 1 minuto, corpo em linha reta.", "Deitado de costas, faça o dead bug baixando devagar braço e perna opostos.", "Passe para quatro apoios no bird dog, esticando braço e perna opostos.", "Termine com 1 minuto de ponte de glúteos e 1 minuto de elevação de pernas.", "Solte o ar sempre que contrair o abdômen."], ["Deixar o quadril cair na prancha.", "Tirar a lombar do chão no dead bug."], "Devagar e com controle vence o rápido; cada repetição bem feita deixa você mais forte."),
    "hi": ExerciseGuide(["1 मिनट फ़ोरआर्म प्लैंक करो, शरीर एक सीधी रेखा में रखो।", "पीठ के बल डेड बग करो, उलटे हाथ और पैर को धीरे से नीचे लाओ।", "हाथों और घुटनों पर बर्ड डॉग करो, उलटा हाथ और पैर फैलाओ।", "आखिर में 1 मिनट ग्लूट ब्रिज और 1 मिनट लेग रेज़ करो।", "हर बार पेट कसते समय साँस छोड़ो।"], ["प्लैंक में कूल्हों को नीचे झुकने देना।", "डेड बग में कमर के निचले हिस्से को ज़मीन से उठाना।"], "धीमा और कंट्रोल्ड तेज़ से बेहतर है, हर सही रेप तुम्हें मज़बूत बनाता है।"),
  },
  "inversion_hang": {
    "en": ExerciseGuide(["Only invert with an adult supervising and on stable, checked equipment.", "Lock your ankles securely and start at a slight incline, not fully upside down.", "Relax your arms and breathe slowly for up to 1 minute.", "Return upright slowly and sit for a moment before standing.", "Stop right away if you feel dizzy, pressure in your head or any pain."], ["Going fully upside down in your first sessions.", "Standing up quickly right after inverting."], "Short, gentle sessions are enough; there is no need to hang longer."),
    "tr": ExerciseGuide(["Sadece bir yetişkinin gözetiminde ve sağlam, kontrol edilmiş ekipmanla ters dön.", "Ayak bileklerini sıkıca sabitle, tam ters değil hafif bir açıyla başla.", "Kollarını gevşet ve en fazla 1 dakika yavaşça nefes al.", "Yavaşça dik konuma dön, ayağa kalkmadan önce biraz otur.", "Baş dönmesi, başında basınç ya da herhangi bir ağrı hissedersen hemen dur."], ["İlk seanslarda tamamen baş aşağı dönmek.", "Ters durduktan hemen sonra hızla ayağa kalkmak."], "Kısa ve nazik seanslar yeterli, süreyi zorlamana gerek yok."),
    "de": ExerciseGuide(["Häng dich nur unter Aufsicht eines Erwachsenen und an stabilem, geprüftem Gerät kopfüber.", "Sichere deine Knöchel fest und starte leicht geneigt, nicht ganz kopfüber.", "Lass die Arme locker und atme bis zu 1 Minute ruhig.", "Komm langsam zurück in die Senkrechte und setz dich kurz, bevor du aufstehst.", "Hör sofort auf, wenn dir schwindlig wird oder du Druck im Kopf oder Schmerzen spürst."], ["In den ersten Einheiten gleich ganz kopfüber gehen.", "Direkt danach zu schnell aufstehen."], "Kurze, sanfte Einheiten reichen völlig, du musst nicht länger hängen."),
    "fr": ExerciseGuide(["Ne t'inverse qu'avec un adulte qui surveille et un matériel stable et vérifié.", "Bloque bien tes chevilles et commence légèrement incliné, pas complètement à l'envers.", "Relâche les bras et respire lentement jusqu'à 1 minute.", "Reviens lentement à la verticale et reste assis un moment avant de te lever.", "Arrête aussitôt en cas de vertige, de pression dans la tête ou de douleur."], ["Te mettre complètement à l'envers dès les premières séances.", "Te relever trop vite juste après l'inversion."], "Des séances courtes et douces suffisent, inutile de rester plus longtemps."),
    "es": ExerciseGuide(["Ponte invertido solo con un adulto supervisando y con equipo estable y revisado.", "Asegura bien los tobillos y empieza con poca inclinación, no del todo boca abajo.", "Relaja los brazos y respira despacio hasta 1 minuto.", "Vuelve despacio a la vertical y siéntate un momento antes de levantarte.", "Para enseguida si notas mareo, presión en la cabeza o cualquier dolor."], ["Ponerte totalmente boca abajo en las primeras sesiones.", "Levantarte de golpe justo después de invertirte."], "Las sesiones cortas y suaves son suficientes; no hace falta alargarlas."),
    "it": ExerciseGuide(["Fallo solo con un adulto che ti controlla e un attrezzo stabile e verificato.", "Blocca bene le caviglie e parti con una leggera inclinazione, non del tutto capovolto.", "Rilassa le braccia e respira piano fino a 1 minuto.", "Torna dritto lentamente e resta seduto un momento prima di alzarti.", "Fermati subito se senti capogiri, pressione alla testa o qualsiasi dolore."], ["Capovolgerti del tutto già nelle prime sessioni.", "Alzarti di scatto subito dopo l'inversione."], "Sessioni brevi e delicate bastano; non serve restare appeso più a lungo."),
    "pt": ExerciseGuide(["Faça só com um adulto supervisionando e com equipamento firme e revisado.", "Prenda bem os tornozelos e comece com pouca inclinação, sem inverter o corpo todo.", "Relaxe os braços e respire devagar por até 1 minuto.", "Volte devagar para a posição vertical e sente um pouco antes de levantar.", "Pare na hora se sentir tontura, pressão na cabeça ou qualquer dor."], ["Ficar totalmente de cabeça para baixo nas primeiras sessões.", "Levantar rápido logo depois da inversão."], "Sessões curtas e suaves bastam; não precisa ficar mais tempo."),
    "hi": ExerciseGuide(["उलटा सिर्फ़ किसी बड़े की निगरानी में और मज़बूत, जाँचे हुए उपकरण पर ही लटको।", "टखनों को अच्छी तरह लॉक करो और हल्के झुकाव से शुरू करो, पूरा उलटा नहीं।", "हाथ ढीले छोड़ो और 1 मिनट तक धीरे-धीरे साँस लो।", "धीरे से सीधे आओ और खड़े होने से पहले थोड़ी देर बैठो।", "चक्कर, सिर में दबाव या कोई भी दर्द हो तो तुरंत रुक जाओ।"], ["पहले ही सेशन में पूरी तरह उलटा हो जाना।", "उलटा लटकने के तुरंत बाद झट से खड़े हो जाना।"], "छोटे और हल्के सेशन काफ़ी हैं, ज़्यादा देर तक लटकने की ज़रूरत नहीं।"),
  },
  "posture_check": {
    "en": ExerciseGuide(["Set an hourly reminder to check how you are sitting or standing.", "Stack your ears over your shoulders and your shoulders over your hips.", "Roll your shoulders back and down, chest gently open.", "Imagine a string pulling the top of your head up, then breathe."], ["Overcorrecting with a stiff, arched back.", "Looking down at your phone with your head pushed forward."], "Raise your screen to eye level and good posture becomes automatic."),
    "tr": ExerciseGuide(["Oturuşunu ve duruşunu kontrol etmek için saatlik hatırlatıcı kur.", "Kulaklarını omuzlarının, omuzlarını kalçanın üstüne hizala.", "Omuzlarını geriye ve aşağı çek, göğsün hafifçe açık olsun.", "Başının tepesini yukarı çeken bir ip hayal et ve nefes al."], ["Sırtını kaskatı ve çukur yaparak aşırı düzeltmek.", "Başın önde, telefona eğilerek bakmak."], "Ekranını göz hizasına kaldır, iyi duruş kendiliğinden gelir."),
    "de": ExerciseGuide(["Stell dir eine stündliche Erinnerung, um deine Haltung zu checken.", "Bring die Ohren über die Schultern und die Schultern über die Hüfte.", "Roll die Schultern nach hinten unten, die Brust ist leicht geöffnet.", "Stell dir einen Faden vor, der deinen Scheitel nach oben zieht, und atme."], ["Mit steifem Hohlkreuz überkorrigieren.", "Mit vorgeschobenem Kopf aufs Handy schauen."], "Bring deinen Bildschirm auf Augenhöhe, dann wird gute Haltung zur Gewohnheit."),
    "fr": ExerciseGuide(["Mets un rappel toutes les heures pour vérifier comment tu es assis ou debout.", "Aligne tes oreilles au-dessus des épaules et tes épaules au-dessus des hanches.", "Ramène les épaules en arrière et vers le bas, poitrine légèrement ouverte.", "Imagine un fil qui tire le sommet de ta tête vers le haut, et respire."], ["Trop corriger avec un dos raide et cambré.", "Regarder ton téléphone la tête en avant."], "Monte ton écran à hauteur des yeux et la bonne posture devient automatique."),
    "es": ExerciseGuide(["Pon un recordatorio cada hora para revisar cómo estás sentado o de pie.", "Coloca las orejas sobre los hombros y los hombros sobre la cadera.", "Lleva los hombros atrás y abajo, con el pecho algo abierto.", "Imagina un hilo que tira de tu coronilla hacia arriba y respira."], ["Corregir de más con la espalda rígida y arqueada.", "Mirar el teléfono con la cabeza adelantada."], "Sube la pantalla a la altura de los ojos y la buena postura saldrá sola."),
    "it": ExerciseGuide(["Imposta un promemoria ogni ora per controllare come sei seduto o in piedi.", "Allinea le orecchie sopra le spalle e le spalle sopra il bacino.", "Porta le spalle indietro e in basso, petto leggermente aperto.", "Immagina un filo che tira la cima della testa verso l'alto e respira."], ["Correggere troppo con la schiena rigida e inarcata.", "Guardare il telefono con la testa in avanti."], "Alza lo schermo all'altezza degli occhi e la buona postura diventa automatica."),
    "pt": ExerciseGuide(["Coloque um lembrete a cada hora para checar como você está sentado ou em pé.", "Alinhe as orelhas sobre os ombros e os ombros sobre o quadril.", "Leve os ombros para trás e para baixo, com o peito levemente aberto.", "Imagine um fio puxando o topo da sua cabeça para cima e respire."], ["Corrigir demais com as costas duras e arqueadas.", "Olhar o celular com a cabeça projetada para frente."], "Coloque a tela na altura dos olhos e a boa postura vira automática."),
    "hi": ExerciseGuide(["हर घंटे का रिमाइंडर लगाओ ताकि बैठने या खड़े होने का तरीका जाँच सको।", "कान कंधों के ऊपर और कंधे कूल्हों के ऊपर एक सीध में रखो।", "कंधों को पीछे और नीचे करो, छाती हल्की खुली रहे।", "सोचो कि एक धागा तुम्हारे सिर को ऊपर खींच रहा है, और साँस लो।"], ["अकड़ी और पीछे मुड़ी पीठ से ज़रूरत से ज़्यादा सुधार करना।", "सिर आगे निकालकर फ़ोन देखना।"], "स्क्रीन को आँखों की ऊँचाई पर रखो, अच्छा पोस्चर अपने आप बनेगा।"),
  },
  "wall_stand": {
    "en": ExerciseGuide(["Stand with your heels against a wall, feet hip-width apart.", "Touch your buttocks, shoulder blades and the back of your head to the wall.", "Tuck your chin slightly and keep your arms relaxed at your sides.", "Hold for 5 minutes, breathing calmly through your nose."], ["Arching your lower back far away from the wall.", "Pushing your chin up instead of keeping it level."], "Notice how this feels, then try to carry it into your day."),
    "tr": ExerciseGuide(["Topukların duvara değsin, ayakların kalça genişliğinde olsun.", "Kalçanı, kürek kemiklerini ve başının arkasını duvara değdir.", "Çeneni hafifçe içeri al, kollarını yanlarda gevşek bırak.", "5 dakika bu şekilde kal, burnundan sakin nefes al."], ["Belini duvardan fazla uzaklaştırıp çukurlaştırmak.", "Çeneni düz tutmak yerine yukarı kaldırmak."], "Bu duruşu iyice hisset, sonra gün içinde de korumaya çalış."),
    "de": ExerciseGuide(["Stell dich mit den Fersen an eine Wand, Füße hüftbreit.", "Po, Schulterblätter und Hinterkopf berühren die Wand.", "Zieh das Kinn leicht ein und lass die Arme locker hängen.", "Halte 5 Minuten und atme ruhig durch die Nase."], ["Den unteren Rücken weit von der Wand wegwölben.", "Das Kinn nach oben schieben, statt es gerade zu halten."], "Spür genau, wie sich das anfühlt, und nimm es mit in deinen Tag."),
    "fr": ExerciseGuide(["Place-toi dos au mur, talons contre le mur, pieds à largeur de hanches.", "Colle tes fesses, tes omoplates et l'arrière de ta tête au mur.", "Rentre légèrement le menton et laisse les bras relâchés le long du corps.", "Tiens 5 minutes en respirant calmement par le nez."], ["Cambrer fort le bas du dos en l'éloignant du mur.", "Lever le menton au lieu de le garder droit."], "Ressens bien cette position, puis essaie de la garder dans ta journée."),
    "es": ExerciseGuide(["Apoya la espalda en la pared con los talones pegados y los pies separados.", "Apoya glúteos, omóplatos y la parte de atrás de la cabeza en la pared.", "Mete un poco la barbilla y deja los brazos relajados a los lados.", "Mantén 5 minutos respirando tranquilo por la nariz."], ["Arquear mucho la zona lumbar separándola de la pared.", "Levantar la barbilla en vez de mantenerla recta."], "Fíjate en cómo se siente esta postura y trata de llevarla a tu día."),
    "it": ExerciseGuide(["Mettiti di spalle al muro con i talloni appoggiati, piedi alla larghezza del bacino.", "Appoggia al muro glutei, scapole e la parte posteriore della testa.", "Porta il mento leggermente indietro e lascia le braccia rilassate lungo il corpo.", "Tieni 5 minuti respirando con calma dal naso."], ["Inarcare molto la zona lombare staccandola dal muro.", "Alzare il mento invece di tenerlo dritto."], "Senti bene questa posizione e prova a portarla con te durante la giornata."),
    "pt": ExerciseGuide(["Fique de costas para a parede com os calcanhares encostados, pés na largura do quadril.", "Encoste glúteos, escápulas e a parte de trás da cabeça na parede.", "Recolha um pouco o queixo e deixe os braços relaxados ao lado do corpo.", "Segure por 5 minutos respirando calmamente pelo nariz."], ["Arquear muito a lombar, afastando-a da parede.", "Levantar o queixo em vez de mantê-lo reto."], "Perceba bem como é essa postura e tente levá-la para o seu dia."),
    "hi": ExerciseGuide(["दीवार से पीठ लगाकर खड़े हो जाओ, एड़ियाँ दीवार से सटी और पैर कूल्हों जितने खुले।", "कूल्हे, कंधे की हड्डियाँ और सिर का पिछला हिस्सा दीवार से छुआओ।", "ठुड्डी हल्की अंदर करो और हाथ बगल में ढीले छोड़ो।", "5 मिनट ऐसे ही रुको और नाक से शांति से साँस लो।"], ["कमर के निचले हिस्से को दीवार से बहुत दूर मोड़ना।", "ठुड्डी सीधी रखने की बजाय ऊपर उठाना।"], "इस मुद्रा को अच्छे से महसूस करो, फिर इसे पूरे दिन बनाए रखने की कोशिश करो।"),
  },
  "neck_stretches": {
    "en": ExerciseGuide(["Sit or stand tall with your shoulders relaxed and down.", "Tilt your ear slowly toward one shoulder and hold 30 seconds per side.", "Lower your chin toward your chest and hold for 30 seconds.", "Lift your gaze gently for 30 seconds without dropping your head back."], ["Pulling hard on your head with your hand.", "Lifting your shoulder up to meet your ear."], "Do these after long study sessions to release tension."),
    "tr": ExerciseGuide(["Dik otur ya da dur, omuzların gevşek ve aşağıda olsun.", "Kulağını yavaşça bir omzuna doğru eğ, her tarafta 30 saniye tut.", "Çeneni göğsüne doğru indir ve 30 saniye tut.", "Başını geriye düşürmeden bakışını yavaşça yukarı kaldır, 30 saniye tut."], ["Elinle başını sertçe çekmek.", "Omzunu kulağına doğru kaldırmak."], "Uzun ders çalışmalarından sonra yap, biriken gerginliği atarsın."),
    "de": ExerciseGuide(["Sitz oder steh aufrecht, die Schultern locker und tief.", "Neig das Ohr langsam zur Schulter und halte 30 Sekunden pro Seite.", "Senk das Kinn zur Brust und halte 30 Sekunden.", "Heb den Blick sanft für 30 Sekunden, ohne den Kopf nach hinten fallen zu lassen."], ["Mit der Hand fest am Kopf ziehen.", "Die Schulter zum Ohr hochziehen."], "Mach das nach langen Lernphasen, um Verspannungen zu lösen."),
    "fr": ExerciseGuide(["Assieds-toi ou tiens-toi droit, épaules basses et détendues.", "Penche lentement l'oreille vers une épaule et tiens 30 secondes de chaque côté.", "Descends le menton vers la poitrine et tiens 30 secondes.", "Lève doucement le regard 30 secondes sans laisser tomber la tête en arrière."], ["Tirer fort sur ta tête avec la main.", "Monter l'épaule vers l'oreille."], "Fais-les après une longue séance de révisions pour relâcher les tensions."),
    "es": ExerciseGuide(["Siéntate o ponte de pie recto, con los hombros relajados y bajos.", "Inclina despacio la oreja hacia un hombro y mantén 30 segundos por lado.", "Baja la barbilla hacia el pecho y mantén 30 segundos.", "Lleva la mirada hacia arriba con suavidad 30 segundos sin echar la cabeza atrás."], ["Tirar fuerte de la cabeza con la mano.", "Subir el hombro hacia la oreja."], "Hazlos después de estudiar mucho rato para soltar tensión."),
    "it": ExerciseGuide(["Siediti o stai in piedi dritto, spalle basse e rilassate.", "Inclina piano l'orecchio verso una spalla e tieni 30 secondi per lato.", "Abbassa il mento verso il petto e tieni 30 secondi.", "Alza lo sguardo con dolcezza per 30 secondi senza buttare la testa indietro."], ["Tirare forte la testa con la mano.", "Alzare la spalla verso l'orecchio."], "Falli dopo lunghe sessioni di studio per sciogliere la tensione."),
    "pt": ExerciseGuide(["Sente ou fique em pé, bem reto, com os ombros relaxados e baixos.", "Incline devagar a orelha até um ombro e segure 30 segundos por lado.", "Leve o queixo em direção ao peito e segure 30 segundos.", "Olhe suavemente para cima por 30 segundos sem jogar a cabeça para trás."], ["Puxar a cabeça com força usando a mão.", "Subir o ombro em direção à orelha."], "Faça depois de longos períodos de estudo para soltar a tensão."),
    "hi": ExerciseGuide(["सीधे बैठो या खड़े हो जाओ, कंधे ढीले और नीचे रखो।", "कान को धीरे से एक कंधे की ओर झुकाओ, हर तरफ 30 सेकंड रुको।", "ठुड्डी को छाती की ओर नीचे लाओ और 30 सेकंड रुको।", "सिर पीछे गिराए बिना नज़र धीरे से ऊपर करो और 30 सेकंड रुको।"], ["हाथ से सिर को ज़ोर से खींचना।", "कंधे को कान की ओर उठाना।"], "लंबी पढ़ाई के बाद ये करो, जमा हुआ तनाव निकल जाएगा।"),
  },
  "shoulder_rolls": {
    "en": ExerciseGuide(["Stand tall with your arms hanging loosely at your sides.", "Roll your shoulders forward in big circles 15 times.", "Roll them backward 15 times, squeezing your shoulder blades together.", "Clasp your hands behind your back and open your chest for 20 seconds."], ["Making tiny, rushed circles.", "Shrugging while holding your breath."], "A quick set between classes or study blocks keeps your shoulders open."),
    "tr": ExerciseGuide(["Dik dur, kolların yanlarda serbestçe sarksın.", "Omuzlarını büyük daireler çizerek 15 kez öne çevir.", "15 kez geriye çevir, kürek kemiklerini arkada sık.", "Ellerini arkada kenetle ve 20 saniye göğsünü aç."], ["Küçük ve aceleci daireler çizmek.", "Nefesini tutarak omuz silkmek."], "Dersler ya da çalışma blokları arasında kısa bir set omuzlarını açık tutar."),
    "de": ExerciseGuide(["Stell dich aufrecht hin, die Arme hängen locker.", "Roll die Schultern 15 Mal in großen Kreisen nach vorn.", "Roll sie 15 Mal nach hinten und zieh dabei die Schulterblätter zusammen.", "Verschränk die Hände hinter dem Rücken und öffne die Brust 20 Sekunden."], ["Kleine, hastige Kreise machen.", "Die Schultern hochziehen und dabei die Luft anhalten."], "Ein kurzer Satz zwischen Schulstunden oder Lernblöcken hält deine Schultern offen."),
    "fr": ExerciseGuide(["Tiens-toi droit, bras relâchés le long du corps.", "Fais rouler tes épaules vers l'avant en grands cercles, 15 fois.", "Fais-les rouler 15 fois vers l'arrière en serrant les omoplates.", "Croise les mains dans le dos et ouvre la poitrine pendant 20 secondes."], ["Faire de petits cercles trop rapides.", "Hausser les épaules en bloquant ta respiration."], "Une petite série entre deux cours ou révisions garde tes épaules ouvertes."),
    "es": ExerciseGuide(["Ponte recto con los brazos sueltos a los lados.", "Gira los hombros hacia delante en círculos grandes 15 veces.", "Gíralos hacia atrás 15 veces, juntando los omóplatos.", "Entrelaza las manos detrás de la espalda y abre el pecho 20 segundos."], ["Hacer círculos pequeños y con prisa.", "Encoger los hombros aguantando la respiración."], "Una serie rápida entre clases o ratos de estudio mantiene tus hombros abiertos."),
    "it": ExerciseGuide(["Stai dritto con le braccia morbide lungo il corpo.", "Ruota le spalle in avanti con cerchi ampi per 15 volte.", "Ruotale indietro 15 volte, stringendo le scapole.", "Intreccia le mani dietro la schiena e apri il petto per 20 secondi."], ["Fare cerchi piccoli e di fretta.", "Alzare le spalle trattenendo il respiro."], "Una serie veloce tra una lezione e l'altra tiene le spalle aperte."),
    "pt": ExerciseGuide(["Fique reto com os braços soltos ao lado do corpo.", "Gire os ombros para frente em círculos grandes, 15 vezes.", "Gire para trás 15 vezes, apertando as escápulas.", "Entrelace as mãos atrás das costas e abra o peito por 20 segundos."], ["Fazer círculos pequenos e apressados.", "Encolher os ombros prendendo a respiração."], "Uma série rápida entre aulas ou estudos mantém seus ombros abertos."),
    "hi": ExerciseGuide(["सीधे खड़े हो जाओ, हाथ बगल में ढीले लटकने दो।", "कंधों को बड़े गोले में 15 बार आगे घुमाओ।", "15 बार पीछे घुमाओ और कंधे की हड्डियों को पीछे की ओर कसो।", "पीठ के पीछे हाथ फँसाओ और 20 सेकंड छाती खोलो।"], ["छोटे और जल्दबाज़ी वाले गोले बनाना।", "साँस रोककर कंधे उचकाना।"], "क्लास या पढ़ाई के बीच एक छोटा सेट तुम्हारे कंधों को खुला रखता है।"),
  },
  "pre_sleep_routine": {
    "en": ExerciseGuide(["Start 30 minutes before bed: dim the lights and put screens away.", "Read a book or listen to calm music for 15 minutes.", "Do 5 minutes of gentle stretching on your bed or the floor.", "Breathe in for 4 seconds and out for 6 seconds, 10 rounds."], ["Scrolling on your phone for just one more minute.", "Changing your bedtime a lot from night to night."], "Same time, same steps every night makes falling asleep easier."),
    "tr": ExerciseGuide(["Yatmadan 30 dakika önce başla: ışıkları kıs, ekranları bırak.", "15 dakika kitap oku ya da sakin müzik dinle.", "Yatağında ya da yerde 5 dakika hafif esneme yap.", "4 saniye nefes al, 6 saniye ver, 10 tur tekrarla."], ["Sadece bir dakika diyerek telefonda gezinmek.", "Yatma saatini geceden geceye çok değiştirmek."], "Her gece aynı saat, aynı adımlar; uykuya dalmak giderek kolaylaşır."),
    "de": ExerciseGuide(["Starte 30 Minuten vor dem Schlafen: Licht dimmen, Bildschirme weglegen.", "Lies 15 Minuten ein Buch oder hör ruhige Musik.", "Dehn dich 5 Minuten sanft auf dem Bett oder dem Boden.", "Atme 4 Sekunden ein und 6 Sekunden aus, 10 Runden lang."], ["Nur noch eine Minute am Handy scrollen.", "Die Schlafenszeit jeden Abend stark verschieben."], "Gleiche Uhrzeit, gleiche Schritte jeden Abend, dann schläfst du leichter ein."),
    "fr": ExerciseGuide(["Commence 30 minutes avant le coucher, lumière tamisée et écrans rangés.", "Lis un livre ou écoute de la musique calme pendant 15 minutes.", "Fais 5 minutes d'étirements doux sur ton lit ou au sol.", "Inspire 4 secondes et expire 6 secondes, pendant 10 cycles."], ["Scroller sur ton téléphone juste une minute de plus.", "Changer beaucoup d'heure de coucher d'un soir à l'autre."], "Même heure, mêmes étapes chaque soir, et tu t'endors plus facilement."),
    "es": ExerciseGuide(["Empieza 30 minutos antes de dormir: baja las luces y deja las pantallas.", "Lee un libro o escucha música tranquila durante 15 minutos.", "Haz 5 minutos de estiramientos suaves en la cama o en el suelo.", "Inhala 4 segundos y exhala 6 segundos, durante 10 rondas."], ["Mirar el teléfono solo un minuto más.", "Cambiar mucho la hora de acostarte cada noche."], "Misma hora y mismos pasos cada noche, así te costará menos dormirte."),
    "it": ExerciseGuide(["Inizia 30 minuti prima di dormire: abbassa le luci e metti via gli schermi.", "Leggi un libro o ascolta musica tranquilla per 15 minuti.", "Fai 5 minuti di allungamenti leggeri sul letto o sul pavimento.", "Inspira per 4 secondi ed espira per 6 secondi, per 10 cicli."], ["Scorrere il telefono solo per un altro minuto.", "Cambiare molto l'orario in cui vai a letto ogni sera."], "Stessa ora e stessi passi ogni sera, così ti addormenti più facilmente."),
    "pt": ExerciseGuide(["Comece 30 minutos antes de dormir: diminua as luzes e largue as telas.", "Leia um livro ou ouça uma música calma por 15 minutos.", "Faça 5 minutos de alongamento leve na cama ou no chão.", "Inspire por 4 segundos e expire por 6 segundos, por 10 rodadas."], ["Rolar o feed do celular só por mais um minuto.", "Mudar muito o horário de dormir de uma noite para outra."], "Mesmo horário e mesmos passos toda noite deixam o sono chegar mais fácil."),
    "hi": ExerciseGuide(["सोने से 30 मिनट पहले शुरू करो, रोशनी धीमी करो और स्क्रीन दूर रखो।", "15 मिनट कोई किताब पढ़ो या शांत संगीत सुनो।", "बिस्तर या ज़मीन पर 5 मिनट हल्की स्ट्रेचिंग करो।", "4 सेकंड साँस लो, 6 सेकंड में छोड़ो, 10 बार दोहराओ।"], ["बस एक मिनट और कहकर फ़ोन स्क्रॉल करना।", "हर रात सोने का समय बहुत बदलना।"], "हर रात एक ही समय और एक ही कदम, इससे नींद आसानी से आती है।"),
  },
  "plank": {
    "en": ExerciseGuide(["Place your forearms on the floor, elbows under your shoulders.", "Step your feet back so your body forms one straight line.", "Squeeze your glutes, pull your belly button in and hold 30 seconds.", "Rest 30 seconds and repeat for 3 sets."], ["Letting your hips sag toward the floor.", "Piking your hips up too high."], "Add 5 seconds each week as it gets easier."),
    "tr": ExerciseGuide(["Ön kollarını yere koy, dirseklerin omuzlarının altında olsun.", "Ayaklarını geriye at, vücudun tek düz bir çizgi oluştursun.", "Kalçanı sık, göbeğini içeri çek ve 30 saniye tut.", "30 saniye dinlen ve 3 set tekrarla."], ["Kalçanın yere doğru sarkması.", "Kalçanın fazla yukarı kalkması."], "Kolaylaştıkça her hafta 5 saniye ekle."),
    "de": ExerciseGuide(["Leg die Unterarme auf den Boden, Ellbogen unter den Schultern.", "Stell die Füße nach hinten, sodass dein Körper eine gerade Linie bildet.", "Spann Po und Bauch an und halte 30 Sekunden.", "Mach 30 Sekunden Pause und wiederhole das für 3 Sätze."], ["Die Hüfte Richtung Boden durchhängen lassen.", "Den Po zu hoch nach oben schieben."], "Leg jede Woche 5 Sekunden drauf, wenn es leichter wird."),
    "fr": ExerciseGuide(["Pose les avant-bras au sol, coudes sous les épaules.", "Recule les pieds pour que ton corps forme une ligne droite.", "Serre les fessiers, rentre le nombril et tiens 30 secondes.", "Repose-toi 30 secondes et fais 3 séries."], ["Laisser les hanches tomber vers le sol.", "Monter les fesses trop haut."], "Ajoute 5 secondes chaque semaine quand ça devient plus facile."),
    "es": ExerciseGuide(["Apoya los antebrazos en el suelo, codos bajo los hombros.", "Lleva los pies atrás hasta que tu cuerpo forme una línea recta.", "Aprieta los glúteos, mete el ombligo y mantén 30 segundos.", "Descansa 30 segundos y repite 3 series."], ["Dejar caer la cadera hacia el suelo.", "Subir la cadera demasiado."], "Suma 5 segundos cada semana cuando te resulte más fácil."),
    "it": ExerciseGuide(["Appoggia gli avambracci a terra, gomiti sotto le spalle.", "Porta i piedi indietro finché il corpo forma una linea retta.", "Stringi i glutei, porta l'ombelico verso l'interno e tieni 30 secondi.", "Riposa 30 secondi e ripeti per 3 serie."], ["Lasciar cadere il bacino verso il pavimento.", "Alzare troppo il bacino."], "Aggiungi 5 secondi ogni settimana quando diventa più facile."),
    "pt": ExerciseGuide(["Apoie os antebraços no chão, cotovelos embaixo dos ombros.", "Leve os pés para trás até o corpo formar uma linha reta.", "Contraia os glúteos, puxe o umbigo para dentro e segure 30 segundos.", "Descanse 30 segundos e repita por 3 séries."], ["Deixar o quadril cair em direção ao chão.", "Empinar o quadril alto demais."], "Acrescente 5 segundos por semana conforme ficar mais fácil."),
    "hi": ExerciseGuide(["फ़ोरआर्म ज़मीन पर टिकाओ, कोहनियाँ कंधों के ठीक नीचे रहें।", "पैर पीछे ले जाओ ताकि शरीर एक सीधी रेखा बने।", "ग्लूट्स कसो, नाभि अंदर खींचो और 30 सेकंड रुको।", "30 सेकंड आराम करो और 3 सेट दोहराओ।"], ["कूल्हों को ज़मीन की ओर झुकने देना।", "कूल्हों को बहुत ऊपर उठा देना।"], "आसान लगने लगे तो हर हफ़्ते 5 सेकंड बढ़ाओ।"),
  },
  "glute_bridge": {
    "en": ExerciseGuide(["Lie on your back, knees bent, feet flat and hip-width apart.", "Press through your heels and lift your hips toward the ceiling.", "Squeeze your glutes at the top for 2 seconds.", "Lower slowly, 12 reps per set, 3 sets in total."], ["Pushing through your toes instead of your heels.", "Overarching your lower back at the top."], "If you feel it in your glutes, not your lower back, you are doing it right."),
    "tr": ExerciseGuide(["Sırtüstü uzan, dizlerin bükük, ayakların kalça genişliğinde yerde olsun.", "Topuklarından iterek kalçanı tavana doğru kaldır.", "Yukarıda kalça kaslarını 2 saniye sık.", "Yavaşça in, her sette 12 tekrar, toplam 3 set yap."], ["Topuk yerine parmak uçlarından itmek.", "Yukarıda belini fazla çukurlaştırmak."], "Belinde değil kalçanda hissediyorsan doğru yapıyorsun."),
    "de": ExerciseGuide(["Leg dich auf den Rücken, Knie gebeugt, Füße hüftbreit flach am Boden.", "Drück dich über die Fersen ab und heb die Hüfte Richtung Decke.", "Spann oben den Po 2 Sekunden lang an.", "Senk dich langsam ab, 12 Wiederholungen pro Satz, 3 Sätze."], ["Über die Zehen statt über die Fersen drücken.", "Oben ins Hohlkreuz gehen."], "Spürst du es im Po und nicht im unteren Rücken, machst du es richtig."),
    "fr": ExerciseGuide(["Allonge-toi sur le dos, genoux pliés, pieds à plat à largeur de hanches.", "Pousse sur les talons et monte le bassin vers le plafond.", "Serre les fessiers en haut pendant 2 secondes.", "Redescends lentement, 12 répétitions par série, 3 séries."], ["Pousser sur les orteils au lieu des talons.", "Trop cambrer le bas du dos en haut."], "Si tu le sens dans les fessiers et pas dans le dos, c'est que tu le fais bien."),
    "es": ExerciseGuide(["Acuéstate boca arriba, rodillas flexionadas, pies planos al ancho de la cadera.", "Empuja con los talones y sube la cadera hacia el techo.", "Aprieta los glúteos arriba durante 2 segundos.", "Baja despacio, 12 repeticiones por serie, 3 series."], ["Empujar con las puntas en vez de con los talones.", "Arquear demasiado la zona lumbar arriba."], "Si lo notas en los glúteos y no en la espalda, lo estás haciendo bien."),
    "it": ExerciseGuide(["Sdraiati sulla schiena, ginocchia piegate, piedi a terra alla larghezza del bacino.", "Spingi sui talloni e solleva il bacino verso il soffitto.", "Stringi i glutei in alto per 2 secondi.", "Scendi piano, 12 ripetizioni per serie, 3 serie."], ["Spingere sulle punte invece che sui talloni.", "Inarcare troppo la zona lombare in alto."], "Se lo senti nei glutei e non nella schiena, lo stai facendo bene."),
    "pt": ExerciseGuide(["Deite de costas, joelhos dobrados, pés no chão na largura do quadril.", "Empurre pelos calcanhares e suba o quadril em direção ao teto.", "Contraia os glúteos lá em cima por 2 segundos.", "Desça devagar, 12 repetições por série, 3 séries."], ["Empurrar pelas pontas dos pés em vez dos calcanhares.", "Arquear demais a lombar lá em cima."], "Se você sente nos glúteos e não nas costas, está fazendo certo."),
    "hi": ExerciseGuide(["पीठ के बल लेटो, घुटने मोड़ो और पैर कूल्हों जितनी चौड़ाई पर ज़मीन पर रखो।", "एड़ियों से दबाकर कूल्हों को छत की ओर उठाओ।", "ऊपर 2 सेकंड ग्लूट्स कसकर रखो।", "धीरे से नीचे आओ, हर सेट में 12 रेप्स, कुल 3 सेट।"], ["एड़ियों की बजाय पंजों से दबाना।", "ऊपर पहुँचकर कमर को ज़्यादा मोड़ना।"], "अगर कमर में नहीं, ग्लूट्स में महसूस हो रहा है, तो तुम सही कर रहे हो।"),
  },
  "calf_raise": {
    "en": ExerciseGuide(["Stand tall next to a wall, fingertips touching it for balance.", "Rise slowly onto the balls of your feet as high as you can.", "Hold 1 second at the top, then lower your heels slowly.", "Do 15 reps per set, 3 sets in total."], ["Bouncing quickly instead of moving slowly.", "Letting your ankles roll outward at the top."], "Do them while brushing your teeth for an easy daily habit."),
    "tr": ExerciseGuide(["Bir duvarın yanında dik dur, denge için parmak uçlarınla dokun.", "Ayak tabanının ön kısmına doğru olabildiğince yükseğe yavaşça kalk.", "Yukarıda 1 saniye bekle, sonra topuklarını yavaşça indir.", "Her sette 15 tekrar, toplam 3 set yap."], ["Yavaş hareket etmek yerine hızlı hızlı yaylanmak.", "Yukarıda ayak bileklerini dışa doğru yatırmak."], "Dişlerini fırçalarken yap, kolay bir günlük alışkanlığa dönüşsün."),
    "de": ExerciseGuide(["Stell dich aufrecht neben eine Wand, die Fingerspitzen zur Balance daran.", "Heb dich langsam so hoch wie möglich auf die Fußballen.", "Halte oben 1 Sekunde und senk die Fersen langsam ab.", "Mach 15 Wiederholungen pro Satz, insgesamt 3 Sätze."], ["Schnell wippen, statt dich langsam zu bewegen.", "Oben mit den Knöcheln nach außen kippen."], "Mach es beim Zähneputzen, so wird es zur einfachen Gewohnheit."),
    "fr": ExerciseGuide(["Tiens-toi droit près d'un mur, le bout des doigts posé dessus.", "Monte lentement sur l'avant des pieds, le plus haut possible.", "Tiens 1 seconde en haut, puis redescends les talons lentement.", "Fais 15 répétitions par série, 3 séries au total."], ["Rebondir vite au lieu de bouger lentement.", "Laisser les chevilles partir vers l'extérieur en haut."], "Fais-les en te brossant les dents, c'est une habitude facile à prendre."),
    "es": ExerciseGuide(["Ponte recto junto a una pared, con la punta de los dedos apoyada.", "Sube despacio sobre la parte delantera del pie lo más alto que puedas.", "Mantén 1 segundo arriba y baja los talones despacio.", "Haz 15 repeticiones por serie, 3 series en total."], ["Rebotar rápido en vez de moverte despacio.", "Dejar que los tobillos se vayan hacia fuera arriba."], "Hazlo mientras te lavas los dientes y será un hábito fácil."),
    "it": ExerciseGuide(["Stai dritto vicino a un muro, con la punta delle dita appoggiata.", "Sali piano sull'avampiede, più in alto che puoi.", "Tieni 1 secondo in alto, poi abbassa piano i talloni.", "Fai 15 ripetizioni per serie, 3 serie in totale."], ["Molleggiare veloce invece di muoverti piano.", "Far piegare le caviglie verso l'esterno in alto."], "Falli mentre ti lavi i denti, così diventa un'abitudine facile."),
    "pt": ExerciseGuide(["Fique reto perto de uma parede, com a ponta dos dedos apoiada nela.", "Suba devagar na parte da frente dos pés, o mais alto que conseguir.", "Segure 1 segundo lá em cima e desça os calcanhares devagar.", "Faça 15 repetições por série, 3 séries no total."], ["Quicar rápido em vez de se mover devagar.", "Deixar os tornozelos virarem para fora lá em cima."], "Faça enquanto escova os dentes e isso vira um hábito fácil."),
    "hi": ExerciseGuide(["दीवार के पास सीधे खड़े हो जाओ, संतुलन के लिए उंगलियों से उसे छुओ।", "पंजों के अगले हिस्से पर जितना हो सके धीरे-धीरे ऊपर उठो।", "ऊपर 1 सेकंड रुको, फिर एड़ियाँ धीरे से नीचे लाओ।", "हर सेट में 15 रेप्स करो, कुल 3 सेट।"], ["धीरे करने की बजाय तेज़ी से उछलना।", "ऊपर टखनों को बाहर की ओर मुड़ने देना।"], "ब्रश करते समय करो, यह रोज़ की आसान आदत बन जाएगी।"),
  },
  "dead_hang_active": {
    "en": ExerciseGuide(["Grip the bar overhand, hands slightly wider than your shoulders.", "Hang with straight arms, then pull your shoulder blades down and back.", "Keep your legs together and core tight, and hold for 20 seconds.", "Step down gently and rest 40 seconds between sets."], ["Bending your elbows like a pull-up.", "Shrugging your shoulders up to your ears."], "Think of pushing the bar away from you to feel your shoulders work."),
    "tr": ExerciseGuide(["Barı üstten kavra, ellerin omuzlarından biraz geniş olsun.", "Kolların düz şekilde asıl, sonra kürek kemiklerini aşağı ve geriye çek.", "Bacaklarını birleştir, karnını sık ve 20 saniye tut.", "Yavaşça in ve setler arasında 40 saniye dinlen."], ["Barfiks çeker gibi dirsekleri bükmek.", "Omuzları kulaklara doğru kaldırmak."], "Barı kendinden uzağa ittiğini düşün, omuzlarının çalıştığını hissedeceksin."),
    "de": ExerciseGuide(["Greif die Stange im Obergriff, Hände etwas breiter als schulterbreit.", "Häng mit gestreckten Armen und zieh die Schulterblätter nach hinten unten.", "Halte die Beine zusammen und den Bauch fest, 20 Sekunden lang.", "Steig sanft ab und mach 40 Sekunden Pause zwischen den Sätzen."], ["Die Ellbogen beugen wie bei einem Klimmzug.", "Die Schultern zu den Ohren hochziehen."], "Stell dir vor, du drückst die Stange von dir weg, dann spürst du deine Schultern arbeiten."),
    "fr": ExerciseGuide(["Attrape la barre en pronation, mains un peu plus écartées que les épaules.", "Suspends-toi bras tendus, puis tire les omoplates vers le bas et l'arrière.", "Jambes serrées et ventre gainé, tiens 20 secondes.", "Redescends doucement et repose-toi 40 secondes entre les séries."], ["Plier les coudes comme pour une traction.", "Monter les épaules vers les oreilles."], "Imagine que tu repousses la barre loin de toi pour sentir tes épaules travailler."),
    "es": ExerciseGuide(["Agarra la barra con las palmas hacia delante, manos algo más abiertas que los hombros.", "Cuelga con los brazos rectos y lleva los omóplatos hacia abajo y atrás.", "Junta las piernas, mantén el abdomen firme y aguanta 20 segundos.", "Baja con suavidad y descansa 40 segundos entre series."], ["Doblar los codos como en una dominada.", "Subir los hombros hacia las orejas."], "Piensa en empujar la barra lejos de ti para sentir cómo trabajan tus hombros."),
    "it": ExerciseGuide(["Afferra la sbarra con presa prona, mani un po' più larghe delle spalle.", "Resta appeso a braccia tese, poi porta le scapole in basso e indietro.", "Tieni le gambe unite e l'addome contratto per 20 secondi.", "Scendi con calma e riposa 40 secondi tra le serie."], ["Piegare i gomiti come in una trazione.", "Alzare le spalle verso le orecchie."], "Immagina di spingere la sbarra lontano da te per sentire lavorare le spalle."),
    "pt": ExerciseGuide(["Segure a barra com as palmas para frente, mãos além da largura dos ombros.", "Fique pendurado com os braços esticados e puxe as escápulas para baixo e para trás.", "Mantenha as pernas juntas e o abdômen firme por 20 segundos.", "Desça com calma e descanse 40 segundos entre as séries."], ["Dobrar os cotovelos como numa barra fixa.", "Subir os ombros em direção às orelhas."], "Pense em empurrar a barra para longe de você para sentir os ombros trabalharem."),
    "hi": ExerciseGuide(["बार को ऊपर से पकड़ो, हाथ कंधों से थोड़े ज़्यादा चौड़े रखो।", "सीधे हाथों से लटको, फिर कंधे की हड्डियों को नीचे और पीछे खींचो।", "पैर साथ रखो, पेट कसो और 20 सेकंड रुको।", "आराम से उतरो और सेट के बीच 40 सेकंड आराम करो।"], ["पुल-अप की तरह कोहनियाँ मोड़ना।", "कंधों को कानों की ओर उचकाना।"], "सोचो कि तुम बार को खुद से दूर धकेल रहे हो, कंधों का काम महसूस होगा।"),
  },
  "cat_cow": {
    "en": ExerciseGuide(["Start on hands and knees, wrists under shoulders, knees under hips.", "Breathe in, drop your belly and lift your chest and gaze (cow).", "Breathe out, round your back and tuck your chin (cat).", "Move slowly with your breath for 10 rounds, 2 sets."], ["Moving faster than your breathing.", "Moving only your neck instead of your whole spine."], "Great as your first move in the morning or a reset after sitting."),
    "tr": ExerciseGuide(["Eller ve dizler üzerinde başla, bilekler omuzların, dizler kalçanın altında.", "Nefes al, karnını aşağı bırak, göğsünü ve bakışını kaldır (inek).", "Nefes ver, sırtını yuvarla ve çeneni içeri al (kedi).", "Nefesinle uyumlu şekilde yavaşça 10 tur yap, toplam 2 set."], ["Nefesinden daha hızlı hareket etmek.", "Tüm omurga yerine sadece boynunu oynatmak."], "Sabahın ilk hareketi ya da uzun oturmanın ardından mola için harika."),
    "de": ExerciseGuide(["Starte im Vierfüßlerstand, Handgelenke unter den Schultern, Knie unter der Hüfte.", "Atme ein, lass den Bauch sinken und heb Brust und Blick (Kuh).", "Atme aus, mach den Rücken rund und zieh das Kinn ein (Katze).", "Beweg dich langsam im Atemrhythmus, 10 Runden, 2 Sätze."], ["Dich schneller bewegen, als du atmest.", "Nur den Nacken statt der ganzen Wirbelsäule bewegen."], "Perfekt als erste Übung am Morgen oder als Pause nach langem Sitzen."),
    "fr": ExerciseGuide(["Commence à quatre pattes, poignets sous les épaules, genoux sous les hanches.", "Inspire, laisse descendre le ventre, lève la poitrine et le regard (vache).", "Expire, arrondis le dos et rentre le menton (chat).", "Bouge lentement au rythme de ta respiration, 10 cycles, 2 séries."], ["Bouger plus vite que ta respiration.", "Bouger seulement la nuque au lieu de toute la colonne."], "Parfait comme premier mouvement le matin ou pour te relancer après être resté assis."),
    "es": ExerciseGuide(["Empieza en cuatro apoyos, muñecas bajo los hombros y rodillas bajo la cadera.", "Inhala, deja caer el abdomen y levanta el pecho y la mirada (vaca).", "Exhala, redondea la espalda y mete la barbilla (gato).", "Muévete despacio al ritmo de tu respiración, 10 rondas, 2 series."], ["Moverte más rápido que tu respiración.", "Mover solo el cuello en vez de toda la columna."], "Ideal como primer movimiento de la mañana o para despejarte tras estar sentado."),
    "it": ExerciseGuide(["Parti a quattro zampe, polsi sotto le spalle, ginocchia sotto le anche.", "Inspira, lascia scendere la pancia e alza petto e sguardo (mucca).", "Espira, arrotonda la schiena e porta il mento verso il petto (gatto).", "Muoviti piano seguendo il respiro, 10 cicli, 2 serie."], ["Muoverti più veloce del tuo respiro.", "Muovere solo il collo invece di tutta la colonna."], "Perfetto come primo movimento del mattino o come pausa dopo tanto tempo seduto."),
    "pt": ExerciseGuide(["Comece em quatro apoios, punhos sob os ombros e joelhos sob o quadril.", "Inspire, solte a barriga e levante o peito e o olhar (vaca).", "Expire, arredonde as costas e recolha o queixo (gato).", "Mova-se devagar no ritmo da respiração, 10 ciclos, 2 séries."], ["Se mover mais rápido que a respiração.", "Mexer só o pescoço em vez da coluna inteira."], "Ótimo como primeiro movimento da manhã ou como pausa depois de ficar sentado."),
